WITH metrics AS (SELECT *, MAX(cost) OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_cost, COUNT(cost) OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_cost, MIN(cost) OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_cost, NTILE(4) OVER (PARTITION BY carrier ORDER BY cost DESC, id) AS cost_bucket FROM shipments) SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, last7_count_cost, last7_min_cost, CASE WHEN carrier RLIKE '^(UPS|Flash)$' THEN 'CORE' WHEN carrier RLIKE '^(DHL|FedEx)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS carrier_zone FROM metrics ORDER BY status NULLS LAST, delivered_date
